package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
	Sleep(time.Duration)
}

// RealClock is the production Clock using time package.
type RealClock struct{}

func (RealClock) Now() time.Time { return time.Now() }
func (RealClock) Sleep(d time.Duration) { time.Sleep(d) }

// TokenBucket implements a concurrency-safe token bucket rate limiter.
type TokenBucket struct {
	mu        sync.Mutex
	clock     Clock
	rate      float64       // tokens per second
	capacity  float64       // maximum tokens
	tokens    float64       // current tokens
	lastRefill time.Time
}

// NewTokenBucket creates a new rate limiter.
// rate must be > 0 and capacity must be > 0.
func NewTokenBucket(rate, capacity float64, clock Clock) (*TokenBucket, error) {
	if rate <= 0 {
		return nil, errors.New("rate must be positive")
	}
	if capacity <= 0 {
		return nil, errors.New("capacity must be positive")
	}
	if clock == nil {
		clock = RealClock{}
	}
	now := clock.Now()
	return &TokenBucket{
		clock:      clock,
		rate:      rate,
		capacity:  capacity,
		tokens:    capacity,
		lastRefill: now,
	}, nil
}

// AllowN reports whether n tokens can be consumed immediately.
// It refills tokens based on elapsed time since last check.
func (tb *TokenBucket) AllowN(n int) bool {
	if n < 0 {
		return false
	}
	tb.mu.Lock()
	defer tb.mu.Unlock()

	now := tb.clock.Now()
	elapsed := now.Sub(tb.lastRefill)
	tb.refillLocked(elapsed)
	if tb.tokens >= float64(n) {
		tb.tokens -= float64(n)
		return true
	}
	return false
}

// refillLocked updates token count based on elapsed time.
func (tb *TokenBucket) refillLocked(elapsed time.Duration) {
	if elapsed <= 0 {
		return
	}
	tb.tokens += float64(elapsed) * tb.rate / float64(time.Second)
	if tb.tokens > tb.capacity {
		tb.tokens = tb.capacity
	}
	tb.lastRefill = tb.lastRefill.Add(elapsed)
}
